public function AardShatterAllowed( actorVictim : CActor, action : W3DamageAction ) : bool
{
	var npcVictim : CNewNPC;
	var dismemberComp : CDismembermentComponent;
	var wounds : array< name >;
	var chance : int;
	var hp, healthLimit : float;

	if( !(W3AardProjectile)action.causer )
		return false;

	npcVictim = (CNewNPC)actorVictim;
	if( !npcVictim )
		return false;

	chance = Options().AardShatterChance();
	if( chance <= 0 )
		return false;

	if( npcVictim.IsHuge() || npcVictim.HasTag('IsBoss') || npcVictim.HasTag('MonsterHuntTarget') )
		return false;

	if( npcVictim.HasAbility('Boss') || npcVictim.HasAbility('SkillBoss') || npcVictim.HasAbility('DisableFinishers') )
		return false;

	if( npcVictim.IsImmuneToInstantKill() )
		return false;

	if( npcVictim.HasAbility('DisableDismemberment') || npcVictim.HasTag('DisableDismemberment') )
		return false;

	healthLimit = Options().AardShatterHealth();
	hp = npcVictim.GetHealthPercents();
	if( hp < 0.f || hp * 100.f > healthLimit )
		return false;

	if( RandRange(100) >= chance )
		return false;

	dismemberComp = (CDismembermentComponent)npcVictim.GetComponentByClassName( 'CDismembermentComponent' );
	if( !dismemberComp )
		return false;

	dismemberComp.GetWoundsNames( wounds, WTF_Explosion );
	if( wounds.Size() == 0 )
		return false;

	return true;
}

